private func recoverySessionBeforeFailure() -> PlaybackSessionRecord? {
    if let lastSettledSession { return lastSettledSession }
    guard let source = state.currentSource, !source.isRemote else { return nil }
    let pending = (pendingPositionRestore ?? pendingPlaybackRestore).flatMap {
        $0.source.representsSameResource(as: source) ? $0 : nil
    }
    // Even a failure between source commit and loaded metadata keeps a
    // source-specific Retry/Locate path. No zero-valued loading checkpoint
    // is substituted for the last available resume intent.
    return PlaybackSessionRecord(source: source, collectionFolder: state.currentFolder,
        playlistItems: state.playlist, playlistIndex: state.currentPlaylistIndex,
        position: ignoresSavedPositionForCurrentSource ? 0
            : (pending?.position ?? persistence.playbackPosition(for: source.url) ?? 0),
        wasPaused: pending?.wasPaused ?? state.isPauseDesired)

defer {
    isDrainingMediaRestore = false
    if checkpointWhenSettled, canCheckpointCurrentPosition { flushSettledCheckpoint() }
}

